// Service worker: cache-first for the app's own files and for Pyodide, so a repeat visit is near-instant and works offline.
// GitHub Pages only caches for about ten minutes and the Pyodide CDN is another origin; this cache does not depend on either.
// sw-manifest.js is generated by scripts/build_bundle.py: { version, pyodide, assets }. A deploy changes `version`, the browser's
// update check sees a different sw-manifest.js, and the new worker replaces the old cache.
importScripts("sw-manifest.js");
const { version, pyodide, assets } = self.LAB;
const APP = "lab-app-" + version, PY = "lab-py-" + pyodide;
const PY_FILES = ["pyodide.mjs", "pyodide.asm.js", "pyodide.asm.wasm", "python_stdlib.zip", "pyodide-lock.json"];

self.addEventListener("install", (e) => {
  e.waitUntil((async () => {
    const app = await caches.open(APP);
    await app.addAll(["./", ...assets]);
    // Pyodide: on a first visit these were just downloaded, so this is filled from the HTTP cache. Best effort: the page works without it.
    try {
      const py = await caches.open(PY);
      const lock = await (await fetch(pyodide + "pyodide-lock.json")).json();
      await py.addAll([...PY_FILES, lock.packages.pyyaml.file_name].map((f) => pyodide + f));
    } catch { /* offline support for Python arrives on a later visit */ }
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith("lab-") && k !== APP && k !== PY) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (e) => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== "GET") return;
  const mine = url.origin === location.origin, py = req.url.startsWith(pyodide);
  if (!mine && !py) return;
  e.respondWith((async () => {
    const cache = await caches.open(py ? PY : APP);
    const hit = await cache.match(mine ? url.pathname.replace(/\/index\.html$/, "/") : req.url, { ignoreSearch: mine });
    if (hit) return hit;
    const res = await fetch(req);
    if (py && res.ok) cache.put(req.url, res.clone());   // a Pyodide file the install step did not list
    return res;
  })());
});
